<?php require_once '../config/database.php';require_once '../includes/functions.php';$base='../';$pageTitle='Koleksi | PinkFlow';$q=trim($_GET['q']??'');$cat=trim($_GET['category']??'');$cats=$conn->query("SELECT DISTINCT category FROM products WHERE is_active=1 AND category<>'' ORDER BY category")->fetch_all(MYSQLI_ASSOC);$sql="SELECT id,name,category,price,image,stock FROM products WHERE is_active=1";$types='';$args=[];if($cat!==''){$sql.=' AND category=?';$types.='s';$args[]=$cat;}if($q!==''){$sql.=' AND (name LIKE ? OR description LIKE ?)';$types.='ss';$args[]="%$q%";$args[]="%$q%";}$sort=$_GET['sort']??'new';$sql.=' ORDER BY '.($sort==='low'?'price ASC':($sort==='high'?'price DESC':'created_at DESC'));$st=$conn->prepare($sql);if($types)$st->bind_param($types,...$args);$st->execute();$items=$st->get_result()->fetch_all(MYSQLI_ASSOC);$pageCss='katalog.css';include '../includes/header.php';?>
<main><section class="pagehero"><span class="eyebrow">FIND YOUR FLOWER</span><h1>Our <em>collection.</em></h1><p>Temukan rangkaian yang tepat untuk setiap cerita.</p></section><section class="section catalog"><aside class="filters"><h3>Categories</h3><a href="katalog.php">All collection</a><?php foreach($cats as $c):?><a href="?category=<?=urlencode($c['category'])?>"><?=e($c['category'])?></a><?php endforeach;?></aside><div><form class="tools"><input name="q" value="<?=e($q)?>" placeholder="Cari buket atau hadiah..."><select name="sort"><option value="new">Terbaru</option><option value="low" <?=$sort==='low'?'selected':''?>>Harga terendah</option><option value="high" <?=$sort==='high'?'selected':''?>>Harga tertinggi</option></select><button class="btn dark">Cari</button></form><div class="products"><?php foreach($items as $p):?><article class="product reveal"><a class="product-img" href="detail.php?id=<?=$p['id']?>"><img src="<?=e(product_image_url($p['image'], $p['name']))?>" alt="<?=e($p['name'])?>" onerror="this.src='https://images.unsplash.com/photo-1490750967868-88aa4486c946?auto=format&fit=crop&w=700&q=80'"></a><small><?=e($p['category'])?> <span><?=rp($p['price'])?></span></small><h3><a href="detail.php?id=<?=$p['id']?>"><?=e($p['name'])?></a></h3><?php if($p['stock']<1):?><small>Stok habis</small><?php endif;?></article><?php endforeach;?></div><?php if(!$items):?><p class="empty">Produk tidak ditemukan.</p><?php endif;?></div></section></main><?php include '../includes/footer.php';?>
